def optimize_matrixpair(out, port, override):
    path = out / 'managed/Game/SwitchRenderMath.cs'
    text = path.read_text()
    head, tail = text.rsplit('\n}', 1)
    path.write_text(head + '\n\n    [System.Runtime.InteropServices.DllImport("FosterPlatform", CallingConvention = System.Runtime.InteropServices.CallingConvention.Cdecl)]\n    private static extern int FosterRenderMatrixPair(in Matrix4x4 a, in Matrix4x4 b, in Matrix4x4 c,\n        out Matrix4x4 first, out Matrix4x4 second);\n\n    public static void MultiplyPair(in Matrix4x4 a, in Matrix4x4 b, in Matrix4x4 c,\n        out Matrix4x4 first, out Matrix4x4 second)\n    {\n        if (FosterRenderMatrixPair(a, b, c, out first, out second) != 0) return;\n        first = Multiply(a, b);\n        second = Multiply(first, c);\n    }\n}' + tail)
    (out / 'foster/switch_matrix_pair.c').write_text((port / 'optimizations/matrixpair.c').read_text())
    override('Graphics/RenderState.cs', [('            matrices.Model = SwitchRenderMath.Multiply(localTransformation, ModelMatrix);\n            matrices.MVP = SwitchRenderMath.Multiply(matrices.Model, Camera.ViewProjection);', '\n            Matrix projection;\n            try { projection = Camera.ViewProjection; }\n            catch\n            {\n                // Preserve the original intermediate value if camera validation\n                // throws; the normal rendering path already has a valid camera.\n                matrices.Model = SwitchRenderMath.Multiply(localTransformation, ModelMatrix);\n                throw;\n            }\n            SwitchRenderMath.MultiplyPair(localTransformation, ModelMatrix, projection,\n                out matrices.Model, out matrices.MVP);')])
